    # ---- Web frameworks --------------------------------------------------
    {"id": "CE-041", "language": "python", "snippet": "from flask import Flask, jsonify\napp = Flask(__name__)\n\n@app.get('/users/<int:user_id>')\ndef get_user(user_id):\n    return jsonify({'id': user_id, 'name': 'Alice'})\n\nif __name__ == '__main__':\n    app.run(debug=True, port=5000)", "purpose": "Minimal Flask REST endpoint with type-converted path parameter", "explanation": "Flask's `<int:user_id>` converter parses the URL segment as int and rejects non-int values with a 404. jsonify wraps the dict as a JSON response with the right Content-Type. debug=True enables auto-reload + interactive tracebacks (never use in production — it allows arbitrary code execution via the debugger console).", "key_concepts": ["Flask routing", "path converters", "JSON response", "debug mode caveat"]},
    {"id": "CE-042", "language": "python", "snippet": "from fastapi import FastAPI\nfrom pydantic import BaseModel\n\napp = FastAPI()\n\nclass User(BaseModel):\n    name: str\n    email: str\n\n@app.post('/users')\ndef create_user(user: User):\n    return {'created': user.name, 'email': user.email}", "purpose": "FastAPI POST endpoint with Pydantic validation", "explanation": "Pydantic models validate the request body against a typed schema; if email is missing or types are wrong, FastAPI returns a 422 with a structured error. The endpoint receives a fully typed User instance. FastAPI auto-generates OpenAPI docs from the type hints. Performance: as fast as Node-equivalents because Pydantic v2 validators are written in Rust.", "key_concepts": ["FastAPI", "Pydantic validation", "type hints as schema", "automatic OpenAPI"]},
    {"id": "CE-043", "language": "javascript", "snippet": "const express = require('express');\nconst app = express();\napp.use(express.json());\n\napp.post('/users', (req, res) => {\n  const { name, email } = req.body;\n  if (!name || !email) return res.status(400).json({ error: 'missing fields' });\n  res.status(201).json({ name, email });\n});\n\napp.listen(3000);", "purpose": "Express POST endpoint with JSON body parsing and validation", "explanation": "express.json() middleware parses JSON request bodies into req.body. Destructuring + truthiness check is the minimal validation; for richer schemas use Joi, Yup, or Zod. Status codes: 201 for created, 400 for client errors. .listen binds the port and starts the server.", "key_concepts": ["Express middleware", "request body parsing", "destructuring validation", "HTTP status codes"]},
    {"id": "CE-044", "language": "go", "snippet": "package main\n\nimport (\n    \"encoding/json\"\n    \"net/http\"\n)\n\ntype User struct {\n    Name  string `json:\"name\"`\n    Email string `json:\"email\"`\n}\n\nfunc main() {\n    http.HandleFunc(\"/users\", func(w http.ResponseWriter, r *http.Request) {\n        var u User\n        if err := json.NewDecoder(r.Body).Decode(&u); err != nil {\n            http.Error(w, err.Error(), http.StatusBadRequest)\n            return\n        }\n        w.Header().Set(\"Content-Type\", \"application/json\")\n        json.NewEncoder(w).Encode(u)\n    })\n    http.ListenAndServe(\":8080\", nil)\n}", "purpose": "Go HTTP handler with struct-tag-driven JSON decoding", "explanation": "Struct tags on User control how json.Decoder maps fields. Decode reads the request body and populates the struct; on parse error, return 400. Encode writes the struct as JSON. Set the Content-Type header before writing the body. For larger services, use chi or gin instead of net/http directly.", "key_concepts": ["struct tags for JSON", "decoder/encoder", "HTTP error handling"]},
    # ---- Database --------------------------------------------------------
    {"id": "CE-045", "language": "python", "snippet": "from sqlalchemy import create_engine, Column, Integer, String\nfrom sqlalchemy.orm import declarative_base, sessionmaker\n\nBase = declarative_base()\nclass User(Base):\n    __tablename__ = 'users'\n    id = Column(Integer, primary_key=True)\n    name = Column(String, nullable=False)\n\nengine = create_engine('sqlite:///app.db')\nBase.metadata.create_all(engine)\nSession = sessionmaker(bind=engine)\nwith Session() as session:\n    session.add(User(name='Alice'))\n    session.commit()", "purpose": "SQLAlchemy ORM: declare schema, create tables, insert a row", "explanation": "declarative_base gives you a base class that maps subclasses to tables via class attributes. create_all issues CREATE TABLE for any tables not yet present. The Session is a unit of work; commit flushes pending changes. The `with` block manages session lifetime cleanly. Use Session.begin() for explicit transactions; SQLAlchemy auto-begins one on first use.", "key_concepts": ["ORM", "declarative mapping", "session as unit of work"]},
    {"id": "CE-046", "language": "python", "snippet": "import sqlite3\n\nconn = sqlite3.connect('app.db')\ncur = conn.cursor()\ncur.execute('SELECT id, name FROM users WHERE active = ?', (1,))\nfor row in cur.fetchall():\n    print(row)\nconn.close()", "purpose": "Raw SQL via sqlite3 with parameterised query", "explanation": "Parameter substitution via `?` placeholders prevents SQL injection — never f-string or % into the query text. fetchall returns all rows; for large results use the cursor as an iterator (`for row in cur:`) to stream. Always close the connection (or use it as a context manager).", "key_concepts": ["parameterised queries", "SQL injection prevention", "cursor as iterator"]},
    {"id": "CE-047", "language": "javascript", "snippet": "const { Pool } = require('pg');\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\n\nasync function getUser(id) {\n  const r = await pool.query(\n    'SELECT id, name FROM users WHERE id = $1',\n    [id]\n  );\n  return r.rows[0];\n}", "purpose": "PostgreSQL parameterised query via node-postgres connection pool", "explanation": "Pool reuses connections across queries — much faster than opening a new connection per request. `$1` is the PG-style positional parameter; the second array argument supplies values, escaped by the driver. r.rows is the result array. Always use parameter binding; never interpolate user input into the SQL string.", "key_concepts": ["connection pooling", "parameterised query", "async/await with DB"]},
