def main() -> int:
    if not BANK.exists():
        print(f"[error] bank not found: {BANK}", file=sys.stderr)
        return 1
    existing_ids = set()
    with BANK.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            existing_ids.add(rec.get("id"))
    print(f"  Existing patterns: {len(existing_ids)}")

    appended = 0
    with BANK.open("a", encoding="utf-8") as f:
        for p in NEW_PATTERNS:
            if p["id"] in existing_ids:
                continue
            f.write(json.dumps(p, ensure_ascii=False) + "\n")
            appended += 1
    print(f"  Appended:          {appended}")
    print(f"  Total now:         {len(existing_ids) + appended}")
    print()
    print("Re-run synth to produce updated SFT corpus:")
    print("  PYTHONPATH=. python3 scripts/synth_code_explain.py \\")
    print("      --bank data/raw/code_explain_patterns.jsonl \\")
    print("      --out data/processed/synth_code_explain.jsonl")
    return 0


if __name__ == "__main__":
    sys.exit(main())
